#!/usr/bin/env node
'use strict';
/* Writes default-rules.json into the guard SDKs as a constant, so the defaults ship without a resource file.
 *   node generate.js          write every target whose SDK folder exists
 *   node generate.js --check  fail when a rules file or vector is invalid or a generated file is out of date */

const fs = require('fs');
const path = require('path');
const { problems, envelopeProblems } = require('./validate');
const { verify } = require('./sign');

const root = path.resolve(__dirname, '..');
const read = f => JSON.parse(fs.readFileSync(path.join(__dirname, f), 'utf8'));
const header = 'Generated by lt-error-guard-spec/generate.js from default-rules.json. Do not edit.';

/** The defaults, the vectors' rules and the contract agree with each other. */
function specProblems() {
  const out = [];
  const defaults = read('default-rules.json');
  out.push(...problems(defaults).map(p => `default-rules.json: ${p}`));
  const domains = JSON.parse(fs.readFileSync(path.join(root, 'lt-telemetry-contract', 'contract.json'), 'utf8')).errorDomains;
  for (const r of defaults.rules) if (r.domain && !domains.includes(r.domain)) out.push(`default-rules.json: ${r.id}: domain ${r.domain} is not a contract error domain`);
  if (!domains.includes('telemetry')) out.push('contract: the budget reports domain telemetry, which the contract lacks');
  for (const c of read('vectors/decisions.json').cases) {
    if (c.rules !== 'default') out.push(...problems(c.rules).map(p => `vectors/decisions.json "${c.name}": ${p}`));
  }
  // The signed fixtures still say what vectors/remote/cases.json expects (an edited file without a new .sig fails here).
  const remote = path.join(__dirname, 'vectors', 'remote');
  const manifest = read('vectors/remote/cases.json');
  const publicPem = fs.readFileSync(path.join(remote, manifest.publicKey), 'utf8');
  for (const c of manifest.cases) {
    const body = fs.readFileSync(path.join(remote, c.file));
    const signed = verify(body, fs.readFileSync(path.join(remote, `${c.file}.sig`), 'utf8'), publicPem);
    const valid = envelopeProblems(JSON.parse(body.toString('utf8'))).length === 0;
    const got = !signed ? 'signature' : !valid ? 'rules' : 'applied';
    const want = c.expect === 'applied' ? 'applied' : c.reason;
    if (got !== want) out.push(`vectors/remote/${c.file}: expected ${want}, the file gives ${got}`);
  }
  for (const c of read('vectors/invalid.json').cases) {
    const found = problems(c.rules);
    if (!found.some(p => p.includes(c.error))) out.push(`vectors/invalid.json "${c.name}": expected a problem with "${c.error}", got ${JSON.stringify(found)}`);
  }
  return out;
}

const kotlin = json => `// ${header}
package com.tswork.lt.errorguard

internal object DefaultRules {
    const val JSON = """
${json.replace(/\$/g, () => "${'$'}")}"""
}
`;

const swift = json => `// ${header}

enum DefaultRules {
    static let json = #"""
${json}
"""#
}
`;

const targets = [
  { dir: 'lt-error-guard-android', file: 'src/main/java/com/tswork/lt/errorguard/DefaultRules.kt', render: kotlin },
  { dir: 'LtErrorGuard-ios', file: 'Sources/LtErrorGuard/DefaultRules.swift', render: swift },
];

function main(args) {
  const check = args.includes('--check');
  const found = specProblems();
  if (found.length) { console.error(found.join('\n')); return 1; }
  const json = fs.readFileSync(path.join(__dirname, 'default-rules.json'), 'utf8').trimEnd();
  let stale = 0;
  for (const t of targets) {
    if (!fs.existsSync(path.join(root, t.dir))) continue;
    const file = path.join(root, t.dir, t.file);
    const text = t.render(json);
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (current === text) continue;
    if (check) { console.error(`out of date: ${path.relative(root, file)} (run node lt-error-guard-spec/generate.js)`); stale++; continue; }
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
    console.log(`wrote ${path.relative(root, file)}`);
  }
  return stale ? 1 : 0;
}

if (require.main === module) process.exitCode = main(process.argv.slice(2));
module.exports = { specProblems, kotlin, swift };
